import{_ as p,o as t,c as a,a4 as _}from"./chunks/framework.C3unmAF4.js";const i=JSON.parse('{"title":"黑土地里探访黑豆绿色种植  AI+激光，精准除草不伤苗（农田里的新鲜事）","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"黑土地里探访黑豆绿色种植  AI+激光，精准除草不伤苗（农田里的新鲜事）","date":"2026-08-06T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202607/t20260724_6486133.htm","summary":"AI激光除草机在作业。\\n明水县委宣传部供图\\n盛夏时节,黑龙江省明水县通泉乡红卫村,连片黑豆田长势正旺。\\n大马力拖拉机缓缓驶过,牵引AI(人工智能)激光除草机平稳前行。设备下方,一道道纤细的蓝色激光扫过垄间苗带,混杂在秧苗里的杂草便被烧断。\\n黑龙江省龙江公社农业种植农民合作社联合社理事长刘运红,跟在农机旁走了半垄地才停下脚步。...\\n","contentHash":"0d875f732e484ee812ee67b896a2271b","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-08-06-黑土地里探访黑豆绿色种植-AI-激光-精准除草不伤苗-农田里的新鲜事.md","filePath":"news/2026-08-06-黑土地里探访黑豆绿色种植-AI-激光-精准除草不伤苗-农田里的新鲜事.md"}'),r={name:"news/2026-08-06-黑土地里探访黑豆绿色种植-AI-激光-精准除草不伤苗-农田里的新鲜事.md"};function n(s,e,o,l,d,A){return t(),a("div",null,[...e[0]||(e[0]=[_('<h1 id="黑土地里探访黑豆绿色种植-ai-激光-精准除草不伤苗-农田里的新鲜事" tabindex="-1">黑土地里探访黑豆绿色种植 AI+激光，精准除草不伤苗（农田里的新鲜事） <a class="header-anchor" href="#黑土地里探访黑豆绿色种植-ai-激光-精准除草不伤苗-农田里的新鲜事" aria-label="Permalink to &quot;黑土地里探访黑豆绿色种植  AI+激光，精准除草不伤苗（农田里的新鲜事）&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202607/t20260724_6486133.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-08-06 摘要: AI激光除草机在作业。 明水县委宣传部供图 盛夏时节,黑龙江省明水县通泉乡红卫村,连片黑豆田长势正旺。 大马力拖拉机缓缓驶过,牵引AI(人工智能)激光除草机平稳前行。设备下方,一道道纤细的蓝色激光扫过垄间苗带,混杂在秧苗里的杂草便被烧断。 黑龙江省龙江公社农业种植农民合作社联合社理事长刘运红,跟在农机旁走了半垄地才停下脚步。...</p></blockquote><p>AI激光除草机在作业。</p><p>明水县委宣传部供图</p><p>盛夏时节,黑龙江省明水县通泉乡红卫村,连片黑豆田长势正旺。</p><p>大马力拖拉机缓缓驶过,牵引AI(人工智能)激光除草机平稳前行。设备下方,一道道纤细的蓝色激光扫过垄间苗带,混杂在秧苗里的杂草便被烧断。</p><p>黑龙江省龙江公社农业种植农民合作社联合社理事长刘运红,跟在农机旁走了半垄地才停下脚步。她蹲下身,指尖捻起一株刚被激光打过的稗草——生长点已经焦枯,而旁边的黑豆苗却叶片鲜亮。</p><p>“以前光会弯腰薅,哪想到激光能除草?”刘运红介绍,有机认证卡得严,要过270多项指标检测,化学除草剂是绝对碰不得的红线。</p><p>杂草种类杂,稗草、狗尾草、苘麻等十几种混着长,一季下来要除3到4遍。过去一个壮劳力忙活一天最多干完一亩地,工钱就要200元。</p><p>雇人也难。每到除草季,村里劳动力不够用,等人凑齐了,草都长过苗梢了。因为没有稳妥的除草方案,有机种植一直不敢贸然扩规模。</p><p>转机从去年开始。刘运红在哈尔滨也有种植基地,哈尔滨华工智耘科技有限公司想在她田里做激光除草试验,她第一次见到了这项技术。</p><p>“纯物理除草,不碰半分农药,这正符合我们的需求。”刘运红没着急拍板,而是上网搜了国外同类产品,发现要贵很多,而且进口设备的识别模型是按国外作物训练的,到了东北黑土地,恐怕认不全本地杂草,容易“水土不服”。</p><p>于是去年一整年,刘运红就跟着研发团队做小规模试验,盯着设备一遍遍地测效果。她还把明水县的杂草样本带给研发团队,陪着技术人员蹲在田里调试AI识别模型。</p><p>今年,AI激光除草机正式大规模投用。</p><p>田埂上,华工智耘农艺部经理姜云峰正盯着操作平板。屏幕上,识别株数、除草数量、作业亩数实时跳动更新。</p><p>“设备是‘眼睛’加‘手术刀’,看得见、打得准、不迷路、行得稳。”姜云峰指着设备介绍,高清摄像头搭配高性能边缘计算平台,每秒上千次扫描田间植株,AI模型几毫秒就能区分豆苗和杂草,伤苗率在0.1%以内;自研激光控制系统配合动态瞄准算法,锁定目标后激光精准照射杂草分生组织,使草体细胞内液体汽化膨胀破裂,破坏分生组织,杂草净除率超95%。</p><p>除此之外,设备搭载自研高精度定位系统,复杂地块也能精准沿垄行进,全程不跑偏;还采用地形自适应稳定移动机器人底盘技术,适应多种路况,可在复杂环境中稳定行走。</p><p>针对东北垄作模式和黑土地杂草种类,团队还专门做了本地化适配。“AI模型实时收集海量数据学习,越用越准。”姜云峰说,通过收集当地各种杂草不同生长周期的样本数据,现在就连刚冒头的小草也能精准识别。</p><p>效率差距更直观。“一天能作业将近100亩。”刘运红算了笔账,这台机器的除草效率是人工的近百倍。</p><p>操作起来也没啥门槛。“就跟玩手机和平板一样,选好对应的作物模型就行。”合作社的操作员潘志远只接受了1小时培训就独立上手了。</p><p>“我们今年一直在收集作业数据和用户反馈,针对黑豆种植的农艺特点持续优化识别模型与作业参数。”姜云峰说,后续还将升级设备性能,优化不同苗龄、不同天气下的作业稳定性,为更多样的农作物提供精准除草服务。</p><p>一笔增收账,算得明明白白。“机器作业成本,比人工降低了一半以上,作物产量还提升了10%至30%。”刘运红算细账,一季下来能省不少钱。</p><p>更可观的是品质带来的溢价。“有机黑豆的收购价,比普通黑豆贵3倍左右。”刘运红说,过去有机种植规模上不去,拿不到稳定的高端订单。现在有了激光除草托底,规模化就有了实打实的盼头。</p><p>村里的种植大户张东天天往田里跑,跟着机器走一趟,蹲下扒开土查草根,心里的疑虑变成了惊喜:“明年我家几十亩豆田都想用上。”还有7个村集体主动对接,想跟合作社一起购置AI激光除草机。</p><p>通泉乡乡长董晓秋这段时间也常泡在田里。在她看来,AI激光除草机带来的不只是除草方式的变化,更是整个产业升级的契机,“除草技术落地了,农户有底气扩种,我们就能顺着有机路子,把黑豆产业做精做强。”</p><p>按照合作规划,华工智耘将与明水县携手打造规模化AI激光除草应用示范区,形成可复制、可推广的智慧农业样板,在更广范围赋能寒地黑土绿色农业发展。</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202607/t20260724_6486133.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',27)])])}const I=p(r,[["render",n]]);export{i as __pageData,I as default};
